package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.*;import android.content.*;import android.os.*;import android.media.AudioManager;import android.net.wifi.WifiManager;import android.widget.*;import java.io.*;import java.util.*;
/** Allowlisted status report; never reads logcat, identifiers, accounts or messages. */
public final class DiagnosticActivity extends LeoActivity {
    private NetworkTelemetry network;private TextView details;private String report="";private boolean refreshing,refreshAgain;
    protected void onCreate(Bundle b){super.onCreate(b);begin(L.t("Diagnostic Leo"));ScrollView scroll=new ScrollView(this);details=text(L.t("Se verifică…"),15);scroll.addView(details);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));network=new NetworkTelemetry(this,new Runnable(){public void run(){refresh();}});left=new Runnable(){public void run(){options(L.t("Diagnostic"),new String[]{L.t("Actualizează"),L.t("Exportă jurnalul tehnic"),L.t("Ce conține raportul?"),L.t("Reconectează serviciul tastelor"),L.t("Șterge lista erorilor Leo")},new Choice(){public void pick(int n){if(n==4){options(L.t("Ștergi tipurile de erori salvate?"),new String[]{L.t("Păstrează"),L.t("Șterge")},new Choice(){public void pick(int yes){if(yes==1){getSharedPreferences("diagnostic-errors",0).edit().remove("items").apply();refresh();}}});}else if(n==0)refresh();else if(n==1)export();else if(n==3){LeoApplication.repairKeys(DiagnosticActivity.this,true);notice(L.t("Reconectare cerută"));}else notice(L.t("Versiuni, servicii, baterie, memorie, spațiu, stare rețea, timpi UI și tipurile ultimelor erori Leo. Fără numere, mesaje, conturi, SSID, IP sau identificatori hardware."));}});}};footer(L.t("Opțiuni"),L.t("Derulează"),L.t("Înapoi"));scroll.setFocusable(true);scroll.requestFocus();}
    protected void onResume(){super.onResume();network.start();refresh();}
    protected void onPause(){network.stop();super.onPause();}
    private void refresh(){if(network==null||details==null)return;if(refreshing){refreshAgain=true;return;}refreshing=true;final String sims=network.summary();worker.execute(new Runnable(){public void run(){final String status=collect(DiagnosticActivity.this,sims);ui(new Runnable(){public void run(){report=status;details.setText(status);refreshing=false;if(refreshAgain){refreshAgain=false;refresh();}}});}});}
    static String collect(Context c,String sims){StringBuilder text=new StringBuilder("LEO · JURNAL TEHNIC\n");text.append("Android ").append(Build.VERSION.RELEASE).append(" · API ").append(Build.VERSION.SDK_INT).append('\n');try{android.content.pm.PackageInfo info=c.getPackageManager().getPackageInfo(c.getPackageName(),0);text.append("Leo ").append(info.versionName).append(L.t(" · cod ")).append(info.versionCode).append("\n");}catch(Exception ignored){}text.append(L.t("Servicii: notificări ")).append(LeoNotificationService.active!=null?L.t("conectat"):L.t("neconectat")).append(L.t(" · muzică ")).append(PlaybackService.instance!=null?L.t("activ"):L.t("oprit")).append(" · FM ").append(FmService.instance!=null?L.t("activ"):L.t("oprit")).append("\n");text.append("Uptime: ").append(SystemClock.elapsedRealtime()/60000).append(" minute\n\n");
        Intent battery=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(battery!=null){int percent=battery.getIntExtra(BatteryManager.EXTRA_LEVEL,0)*100/Math.max(1,battery.getIntExtra(BatteryManager.EXTRA_SCALE,100));text.append(L.t("Baterie: ")).append(percent).append("% · ").append(battery.getIntExtra(BatteryManager.EXTRA_PLUGGED,0)==0?L.t("pe baterie"):L.t("încărcare")).append('\n');text.append(L.t("Temperatură: ")).append(battery.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,0)/10f).append(" °C\n");}
        ActivityManager am=(ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE);ActivityManager.MemoryInfo memory=new ActivityManager.MemoryInfo();am.getMemoryInfo(memory);text.append(L.t("RAM disponibilă: ")).append(memory.availMem/1048576).append(" / ").append(memory.totalMem/1048576).append(" MiB\n");try{Debug.MemoryInfo[] own=am.getProcessMemoryInfo(new int[]{android.os.Process.myPid()});text.append(L.t("Proces Leo PSS: ")).append(own[0].getTotalPss()/1024).append(" MiB\n");}catch(RuntimeException ignored){}
        text.append(L.t("Presiune RAM: ")).append(memory.lowMemory?L.t("ridicată"):L.t("normală")).append("\n\n");appendStorage(text,L.t("Date interne"),Environment.getDataDirectory());for(Map.Entry<String,File> entry:LeoFileProvider.roots(c).entrySet())if(!entry.getKey().equals("leo"))appendStorage(text,entry.getKey().equals("phone")?L.t("Fișiere telefon"):L.t("Card SD"),entry.getValue());
        text.append('\n').append(sims).append('\n');WifiManager wifi=(WifiManager)c.getApplicationContext().getSystemService(Context.WIFI_SERVICE);text.append("Wi-Fi: ").append(wifi==null?L.t("indisponibil"):wifi.isWifiEnabled()?L.t("pornit"):L.t("oprit")).append('\n');text.append(L.t("Placă audio: ")).append(PlaybackService.hardwareReady()?L.t("prezentă"):L.t("indisponibilă")).append('\n');AudioManager audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);text.append(L.t("Volum muzică: ")).append(audio.getStreamVolume(AudioManager.STREAM_MUSIC)).append('/').append(audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC)).append("\n\n");text.append("USB gadget: ").append(readStatus("/sys/class/udc/msm_hsusb/state")).append(" · runtime ").append(readStatus("/sys/devices/platform/soc/78d9000.usb/power/runtime_status")).append("\n");text.append("FM: ").append(new File("/dev/radio0").exists()?L.t("dispozitiv prezent · Radio FM Leo"):L.t("dispozitiv absent")).append('\n');boolean wired=false;for(android.media.AudioDeviceInfo device:audio.getDevices(AudioManager.GET_DEVICES_OUTPUTS))if(device.getType()==android.media.AudioDeviceInfo.TYPE_WIRED_HEADPHONES||device.getType()==android.media.AudioDeviceInfo.TYPE_WIRED_HEADSET)wired=true;text.append(L.t("Căști cu fir: ")).append(wired?L.t("detectate"):L.t("nedetectate")).append("\n\n");text.append(L.t("Serviciu taste: ")).append(LeoPointerService.connected()?L.t("conectat"):L.t("neconectat")).append(L.t("\nÎntârziere maximă UI vizibilă: ")).append(LeoApplication.worstDelay).append(" ms\n");text.append(UiMetrics.snapshot()).append(L.t("\n\nRaport cu câmpuri limitate; fără date personale sau logcat.\n"));text.append("\n").append(FaultLedger.report(c));return text.toString();}
    private static String readStatus(String path){try(BufferedReader input=new BufferedReader(new FileReader(path))){String line=input.readLine();return line==null?L.t("necunoscut"):line.substring(0,Math.min(32,line.length()));}catch(IOException e){return L.t("indisponibil");}}
    private static void appendStorage(StringBuilder text,String label,File root){try{StatFs stat=new StatFs(root.getPath());text.append(label).append(": ").append(stat.getAvailableBytes()/1048576).append(" / ").append(stat.getTotalBytes()/1048576).append(L.t(" MiB liberi\n"));}catch(RuntimeException ignored){text.append(label).append(": indisponibil\n");}}
    private void export(){if(report.isEmpty())return;LinearLayout fields=fields(L.t("Previzualizare raport"));final EditText edited=field(fields,L.t("Poți șterge orice rând înainte de export"),report,android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);edited.setSingleLine(false);left=new Runnable(){public void run(){final String snapshot=edited.getText().toString();if(snapshot.length()>65536){notice(L.t("Raport prea mare"));return;}options(L.t("Salvezi raportul local?"),new String[]{L.t("Continuă editarea"),L.t("Salvează copia verificată")},new Choice(){public void pick(int yes){if(yes==1)saveReport(snapshot);}});}};back=new Runnable(){public void run(){finish();}};footer(L.t("Salvează"),"Editor",L.t("Șterge"));edited.requestFocus();}
    private void saveReport(final String snapshot){worker.execute(new Runnable(){public void run(){try{File directory=new File(getFilesDir(),"documents");if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException();android.util.AtomicFile file=new android.util.AtomicFile(new File(directory,"leo-diagnostic.txt"));FileOutputStream output=null;try{output=file.startWrite();output.write(snapshot.getBytes("UTF-8"));file.finishWrite(output);}catch(IOException e){if(output!=null)file.failWrite(output);throw e;}ui(new Runnable(){public void run(){notice(L.t("Salvat: Fișiere Leo → Documente Leo → leo-diagnostic.txt"));}});}catch(IOException e){ui(new Runnable(){public void run(){notice(L.t("Raportul nu a putut fi salvat"));}});}}});}
}
